  sql = `WITH ins AS (\n  INSERT INTO public.member_list_mailout_recipients (job_id, recipient_name, to_address, status, error_message, failed_at, metadata)\n  VALUES (${sqlLiteral(jobId)}::uuid, ${sqlLiteral(recipientName)}, ${sqlLiteral(actualTo)}, 'Failed', ${sqlLiteral(errorMsg)}, now(), ${sqlLiteral(JSON.stringify(metadataObj))}::jsonb)\n  RETURNING id::text AS recipient_id\n), upd AS (\n  UPDATE public.member_list_mailout_jobs SET failed_count = COALESCE(failed_count, 0) + 1 WHERE id = ${sqlLiteral(jobId)}::uuid\n)\nSELECT recipient_id FROM ins`;
} else {
  sql = `WITH ins AS (\n  INSERT INTO public.member_list_mailout_recipients (job_id, recipient_name, to_address, cc_address, bcc_address, internet_message_id, gmail_message_id, status, open_tracking_token, open_tracking_enabled, open_status, sent_at, metadata)\n  VALUES (${sqlLiteral(jobId)}::uuid, ${sqlLiteral(recipientName)}, ${sqlLiteral(actualTo)}, NULL, NULL, ${sqlLiteral(internetMessageId)}, ${sqlLiteral(gmailMessageId)}, 'Sent', ${trackingToken ? sqlLiteral(trackingToken) + '::uuid' : 'NULL'}, ${chunkPayload.open_tracking_enabled ? 'TRUE' : 'FALSE'}, ${chunkPayload.open_tracking_enabled && trackingToken ? "'Not Opened'" : "'Not Tracked'"}, now(), ${sqlLiteral(JSON.stringify(metadataObj))}::jsonb)\n  RETURNING id::text AS recipient_id\n), upd AS (\n  UPDATE public.member_list_mailout_jobs SET sent_count = sent_count + 1 WHERE id = ${sqlLiteral(jobId)}::uuid\n)\nSELECT recipient_id FROM ins`;
}
return { json: { ...chunkPayload, internet_message_id: internetMessageId, gmail_message_id: gmailMessageId, was_error: hasError, error_message: errorMsg, sql } };

const results = $('Log Resume Recipient').all().map(item => item.json ?? {});
const buildResults = $('Build Resume Log SQL').all().map(item => item.json ?? {});
const firstChunk = $('Build Resume Chunks').first()?.json ?? {};
const jobId = firstChunk.job_id || '';
const sqlLiteral = (value) => value === null || value === undefined ? 'NULL' : "'" + String(value).replace(/'/g, "''") + "'";
const sentCount = results.filter(r => r.recipient_id).length;
const anyFailed = buildResults.some(r => r.was_error);
const status = anyFailed ? 'Paused' : 'Completed';
const sql = jobId
  ? `UPDATE public.member_list_mailout_jobs SET status = '${status}', completed_at = ${status === 'Completed' ? 'now()' : 'NULL'} WHERE id = ${sqlLiteral(jobId)}::uuid`
  : 'SELECT 1';
return [{ json: { sql, job_id: jobId, sent_count: sentCount, any_failed: anyFailed, status } }];

const firstChunk = $('Build Resume Chunks').first()?.json ?? {};
const completeResult = $('Build Resume Complete SQL').first()?.json ?? {};
const logs = $('Build Resume Log SQL').all().map(i => i.json ?? {});
const clean = (v) => v === null || v === undefined ? '' : String(v).trim();
